-- =========================================================================
-- ONE-PASTE SETUP for the Supabase SQL editor.
--
-- Generated by joining every file in supabase/migrations/ in order, then the
-- coach rows.
--
-- PREFER `node scripts/apply-sql.mjs supabase/migrations/*.sql`, which runs
-- each file in its own transaction. The SQL editor wraps a whole paste in one,
-- and 0008 adds a value to an enum -- Postgres forbids *using* a new enum
-- value in the transaction that added it. Nothing here does, so this should
-- work; but if it stops on 0008, apply the migrations one at a time instead.
--
-- Do not edit this file. Edit the sources and regenerate:
--   bash supabase/build_setup_all.sh
--
-- Running it twice will fail on the first duplicate row -- that is deliberate,
-- it means the database already has this data.
-- =========================================================================


-- ===== supabase/migrations/0001_initial_schema.sql =====

-- Chess Center Progress Dashboard — initial schema
-- Contains NO student data. Placeholder rows live in supabase/seed/ and are
-- deleted before the real import. Never put seed data in this file.

-- ---------------------------------------------------------------------------
-- Status enum
-- ---------------------------------------------------------------------------
create type progress_status as enum (
  'not_seen',
  'seen',
  'needs_testing',
  'checked_off'
);

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

-- Coaches. Rows are created manually; there is no public signup.
create table coaches (
  id           uuid primary key references auth.users (id) on delete cascade,
  display_name text        not null,
  created_at   timestamptz not null default now()
);

create table levels (
  id         uuid primary key default gen_random_uuid(),
  number     int         not null unique,
  name       text        not null,
  created_at timestamptz not null default now()
);

-- "order" is reserved in Postgres, hence sort_order.
create table topics (
  id         uuid primary key default gen_random_uuid(),
  level_id   uuid        not null references levels (id) on delete cascade,
  name       text        not null,
  sort_order int         not null,
  created_at timestamptz not null default now(),
  unique (level_id, sort_order)
);

-- is_active supports "remove a student" without destroying their record.
create table students (
  id               uuid primary key default gen_random_uuid(),
  full_name        text        not null,
  current_level_id uuid        references levels (id),
  is_active        boolean     not null default true,
  created_at       timestamptz not null default now()
);

-- The permanent record. No level column: a row's level is reached through
-- topic_id -> topics.level_id. Promoting a student therefore touches nothing
-- here, so past-level history survives automatically.
create table progress (
  student_id uuid            not null references students (id) on delete cascade,
  topic_id   uuid            not null references topics (id)   on delete cascade,
  status     progress_status not null default 'not_seen',
  updated_at timestamptz     not null default now(),
  updated_by uuid            references coaches (id),
  primary key (student_id, topic_id)
);

create table sessions (
  id           uuid primary key default gen_random_uuid(),
  session_date date        not null,
  session_time time,
  created_by   uuid        references coaches (id),
  created_at   timestamptz not null default now()
);

create table attendance (
  session_id uuid        not null references sessions (id) on delete cascade,
  student_id uuid        not null references students (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (session_id, student_id)
);

-- Free-text notepad, one per student per session. Coaches use their own
-- shorthand; this is deliberately unstructured.
create table session_notes (
  session_id uuid        not null references sessions (id) on delete cascade,
  student_id uuid        not null references students (id) on delete cascade,
  note_text  text        not null default '',
  updated_at timestamptz not null default now(),
  updated_by uuid        references coaches (id),
  primary key (session_id, student_id)
);

-- ---------------------------------------------------------------------------
-- Indexes for the hot paths (session grid, roster, focus mode)
-- ---------------------------------------------------------------------------
create index topics_level_order_idx   on topics (level_id, sort_order);
create index students_active_idx      on students (is_active, full_name);
create index progress_student_idx     on progress (student_id);
create index attendance_session_idx   on attendance (session_id);
create index sessions_date_idx        on sessions (session_date desc);

-- ---------------------------------------------------------------------------
-- Auto-create progress rows
--
-- When a student is added with a level, or moved to a new level, they need a
-- not_seen row for every topic in that level so the grid renders a full row
-- instead of gaps. ON CONFLICT DO NOTHING means existing statuses are never
-- overwritten -- including on a move back to a previously-held level.
-- ---------------------------------------------------------------------------
create or replace function public.ensure_progress_rows(p_student_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into progress (student_id, topic_id, status)
  select s.id, t.id, 'not_seen'::progress_status
    from students s
    join topics   t on t.level_id = s.current_level_id
   where s.id = p_student_id
  on conflict (student_id, topic_id) do nothing;
end;
$$;

create or replace function public.students_ensure_progress()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.current_level_id is not null then
    perform public.ensure_progress_rows(new.id);
  end if;
  return new;
end;
$$;

create trigger students_ensure_progress_ins
  after insert on students
  for each row
  execute function public.students_ensure_progress();

create trigger students_ensure_progress_upd
  after update of current_level_id on students
  for each row
  when (new.current_level_id is distinct from old.current_level_id)
  execute function public.students_ensure_progress();

-- ---------------------------------------------------------------------------
-- updated_at maintenance
-- ---------------------------------------------------------------------------
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger progress_touch_updated_at
  before update on progress
  for each row execute function public.touch_updated_at();

create trigger session_notes_touch_updated_at
  before update on session_notes
  for each row execute function public.touch_updated_at();

-- ---------------------------------------------------------------------------
-- Row-level security
--
-- Access model: you must be an authenticated coach to touch anything.
-- ---------------------------------------------------------------------------
create or replace function public.is_coach()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (select 1 from coaches where id = auth.uid());
$$;

alter table coaches       enable row level security;
alter table levels        enable row level security;
alter table topics        enable row level security;
alter table students      enable row level security;
alter table progress      enable row level security;
alter table sessions      enable row level security;
alter table attendance    enable row level security;
alter table session_notes enable row level security;

-- The coaches table gets a plain read-all policy rather than is_coach().
-- is_coach() reads this table, so using it here would be self-referential.
-- Only coaches can authenticate (public signup is disabled), so read-all for
-- authenticated is equivalent in practice. No write policies: coach rows are
-- managed with the secret key, never through the client.
create policy "coaches readable by authenticated"
  on coaches for select to authenticated
  using (true);

create policy "coach full access" on levels        for all to authenticated using (public.is_coach()) with check (public.is_coach());
create policy "coach full access" on topics        for all to authenticated using (public.is_coach()) with check (public.is_coach());
create policy "coach full access" on students      for all to authenticated using (public.is_coach()) with check (public.is_coach());
create policy "coach full access" on progress      for all to authenticated using (public.is_coach()) with check (public.is_coach());
create policy "coach full access" on sessions      for all to authenticated using (public.is_coach()) with check (public.is_coach());
create policy "coach full access" on attendance    for all to authenticated using (public.is_coach()) with check (public.is_coach());
create policy "coach full access" on session_notes for all to authenticated using (public.is_coach()) with check (public.is_coach());

-- ===== supabase/migrations/0002_curriculum_editing.sql =====

-- Curriculum editing helpers
--
-- The coaches maintain their own topic lists from the Curriculum page, so both
-- of these run as the caller (security invoker): row-level security still
-- applies, and only a coach can move or add anything.

-- ---------------------------------------------------------------------------
-- Reorder a topic by one place.
--
-- Done in the database because topics carry a unique (level_id, sort_order):
-- a swap performed as two client round trips would either collide half way or
-- leave a gap if the second call never arrived. Inside one function it is a
-- single transaction that cannot land half done.
-- ---------------------------------------------------------------------------
create or replace function public.move_topic(p_topic_id uuid, p_direction int)
returns void
language plpgsql
set search_path = public
as $$
declare
  v_level       uuid;
  v_order       int;
  v_other_id    uuid;
  v_other_order int;
begin
  select level_id, sort_order into v_level, v_order
    from topics where id = p_topic_id;

  if v_level is null then
    return;
  end if;

  if p_direction < 0 then
    select id, sort_order into v_other_id, v_other_order
      from topics
     where level_id = v_level and sort_order < v_order
     order by sort_order desc
     limit 1;
  else
    select id, sort_order into v_other_id, v_other_order
      from topics
     where level_id = v_level and sort_order > v_order
     order by sort_order asc
     limit 1;
  end if;

  -- Already at the top or the bottom of its level.
  if v_other_id is null then
    return;
  end if;

  -- The unique constraint is checked per statement, so park the moving row on
  -- a value no real topic can hold before writing the swap.
  update topics set sort_order = -1            where id = p_topic_id;
  update topics set sort_order = v_order       where id = v_other_id;
  update topics set sort_order = v_other_order where id = p_topic_id;
end;
$$;

-- ---------------------------------------------------------------------------
-- Append a topic to a level.
--
-- Computing max(sort_order) + 1 in the client would let two coaches adding a
-- topic at the same moment pick the same number and one of them lose the write
-- to the unique constraint.
-- ---------------------------------------------------------------------------
create or replace function public.add_topic(p_level_id uuid, p_name text)
returns uuid
language plpgsql
set search_path = public
as $$
declare
  v_id uuid;
begin
  insert into topics (level_id, name, sort_order)
  select p_level_id,
         p_name,
         coalesce(max(sort_order), 0) + 1
    from topics
   where level_id = p_level_id
  returning id into v_id;

  -- Every student sitting in this level needs a row for the new topic,
  -- otherwise their grid renders one cell short.
  insert into progress (student_id, topic_id, status)
  select s.id, v_id, 'not_seen'::progress_status
    from students s
   where s.current_level_id = p_level_id
  on conflict (student_id, topic_id) do nothing;

  return v_id;
end;
$$;

-- ===== supabase/migrations/0003_grants.sql =====

-- Table privileges for the API roles
--
-- Row-level security decides *which rows* a request may touch. It does not
-- grant the underlying table privilege, and Postgres checks the GRANT first.
-- Tables created through the Supabase dashboard inherit grants from that
-- role's default privileges; these were created over a direct psql-style
-- connection as `postgres`, which does not, so every policy in 0001 sat on a
-- table the API roles could not read at all:
--
--   permission denied for table students   (42501)
--
-- Granting broadly here is safe precisely because the policies are the real
-- gate: every one of them requires public.is_coach().

grant usage on schema public to authenticated;

-- Coaches is read-only from the client. Rows are created with the secret key
-- when an account is set up, never through the app.
grant select on public.coaches to authenticated;

grant select, insert, update, delete on
  public.levels,
  public.topics,
  public.students,
  public.progress,
  public.sessions,
  public.attendance,
  public.session_notes
to authenticated;

grant execute on function public.move_topic(uuid, int)  to authenticated;
grant execute on function public.add_topic(uuid, text)  to authenticated;

-- Anonymous requests get nothing: there are no public pages beyond /login,
-- and the login form talks to the auth API rather than to these tables.
revoke all on all tables in schema public from anon;

-- Tables added by later migrations inherit the same grants, so this class of
-- failure cannot come back.
alter default privileges in schema public
  grant select, insert, update, delete on tables to authenticated;

-- ===== supabase/migrations/0004_recurring_classes.sql =====

-- Recurring classes
--
-- A class that runs every Wednesday and Friday should be described once, not
-- created by hand each week. A series holds that description; the sessions it
-- produces stay ordinary rows, so attendance, the grid and notes are unchanged
-- and a one-off class still works exactly as before.
--
-- Sessions are materialised rather than computed on the fly. A coach needs to
-- be able to cancel one week, or add a session that is not on the timetable,
-- without fighting a rule that keeps regenerating it.

create table class_series (
  id           uuid primary key default gen_random_uuid(),
  name         text        not null,
  -- 0 = Sunday through 6 = Saturday, matching extract(dow).
  weekdays     int[]       not null check (
                 array_length(weekdays, 1) between 1 and 7
                 and weekdays <@ array[0, 1, 2, 3, 4, 5, 6]
               ),
  session_time time,
  is_active    boolean     not null default true,
  created_at   timestamptz not null default now(),
  created_by   uuid        references coaches (id)
);

alter table sessions
  add column series_id uuid references class_series (id) on delete set null;

-- One session per series per day. This is what makes generation repeatable:
-- running it again fills in only the dates that are missing.
create unique index sessions_series_date_idx
  on sessions (series_id, session_date)
  where series_id is not null;

create index sessions_series_idx on sessions (series_id);

-- ---------------------------------------------------------------------------
-- Materialise a series' classes up to a date.
--
-- Never backfills: generation starts at today, so switching a class from
-- Tuesdays to Thursdays does not invent history. Returns how many were
-- created, which is what the page reports back to the coach.
-- ---------------------------------------------------------------------------
create or replace function public.generate_series_sessions(
  p_series_id uuid,
  p_through   date
)
returns int
language plpgsql
set search_path = public
as $$
declare
  v_created int;
begin
  insert into sessions (session_date, session_time, series_id, created_by)
  select day::date, s.session_time, s.id, s.created_by
    from class_series s
    cross join generate_series(current_date, p_through, interval '1 day') as day
   where s.id = p_series_id
     and s.is_active
     and extract(dow from day)::int = any (s.weekdays)
  on conflict do nothing;

  get diagnostics v_created = row_count;
  return v_created;
end;
$$;

-- ---------------------------------------------------------------------------
-- Privileges. As in 0003, the policies below are the real gate.
-- ---------------------------------------------------------------------------
alter table class_series enable row level security;

create policy "coach full access" on class_series
  for all to authenticated
  using (public.is_coach())
  with check (public.is_coach());

grant select, insert, update, delete on public.class_series to authenticated;
grant execute on function public.generate_series_sessions(uuid, date) to authenticated;

-- ===== supabase/migrations/0005_series_start_date.sql =====

-- A repeating class needs a start date
--
-- Without one, generation could only ever begin today, so a coach setting up
-- next term's timetable in the holidays got nothing until term started. The
-- start date is the coach's stated intent, so generation honours it in both
-- directions: a future date waits, a past date fills in the classes that have
-- already happened, which is how a term gets recorded after the fact.

alter table class_series
  add column start_date date not null default current_date;

create or replace function public.generate_series_sessions(
  p_series_id uuid,
  p_through   date
)
returns int
language plpgsql
set search_path = public
as $$
declare
  v_created int;
begin
  insert into sessions (session_date, session_time, series_id, created_by)
  select day::date, s.session_time, s.id, s.created_by
    from class_series s
    cross join generate_series(s.start_date, p_through, interval '1 day') as day
   where s.id = p_series_id
     and s.is_active
     and extract(dow from day)::int = any (s.weekdays)
  on conflict do nothing;

  get diagnostics v_created = row_count;
  return v_created;
end;
$$;

-- ===== supabase/migrations/0006_realtime.sql =====

-- Publish the tables two coaches can edit at the same time
--
-- Brad and Tim work the same class from two devices. Without this, the later
-- write silently wins and neither screen shows the other's marks until it is
-- reloaded -- and a session note, which saves as whole text, loses a paragraph
-- rather than a cell.
--
-- Realtime respects row-level security: a subscriber is sent a change only if
-- their own policies would have let them read the row, so publishing these
-- tables does not widen access. Nothing here is readable without a coach
-- account.

do $$
begin
  if not exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    create publication supabase_realtime;
  end if;
end
$$;

do $$
declare
  v_table text;
begin
  foreach v_table in array array['progress', 'attendance', 'session_notes'] loop
    if not exists (
      select 1
        from pg_publication_tables
       where pubname = 'supabase_realtime'
         and schemaname = 'public'
         and tablename = v_table
    ) then
      execute format('alter publication supabase_realtime add table public.%I', v_table);
    end if;
  end loop;
end
$$;

-- Send the whole row on update and delete, not just the primary key. Without
-- it a deleted attendance row arrives too thin to match against the session on
-- screen, and an updated note arrives without the text it replaced.
alter table public.progress      replica identity full;
alter table public.session_notes replica identity full;
alter table public.attendance    replica identity full;

-- ===== supabase/migrations/0007_tighten_privileges.sql =====

-- Close two gaps found auditing the live database
--
-- 1. TRUNCATE is not filtered by row-level security. A policy that restricts
--    which rows you may delete does nothing about a statement that empties the
--    table, so holding TRUNCATE is holding "erase everything" regardless of
--    what the policies say. Nobody needs it through the API.
--
-- 2. class_series was created in 0004, after 0003 revoked anon's privileges,
--    so it inherited a fresh set and anon ended up holding TRUNCATE on it.
--    Any table added later would do the same, hence the default privileges
--    below as well as the one-off revoke.
--
-- Also narrows the coaches table: the app only ever needs the signed-in
-- coach's own row, and a signed-in stranger should not be able to enumerate
-- the staff.

-- ---------------------------------------------------------------------------
-- Anonymous requests get nothing in this schema, now and in future
-- ---------------------------------------------------------------------------
revoke all on all tables in schema public from anon;
alter default privileges in schema public revoke all on tables from anon;

-- ---------------------------------------------------------------------------
-- Coaches keep row access but lose the table-wide hammer
-- ---------------------------------------------------------------------------
revoke truncate on all tables in schema public from authenticated;
alter default privileges in schema public revoke truncate on tables from authenticated;

-- ---------------------------------------------------------------------------
-- service_role is the admin path used by import and maintenance tooling. It
-- bypasses RLS by design; it was left without the ordinary grants on tables
-- created after 0003, which would fail confusingly at import time.
-- ---------------------------------------------------------------------------
grant select, insert, update, delete on all tables in schema public to service_role;
alter default privileges in schema public
  grant select, insert, update, delete on tables to service_role;

-- ---------------------------------------------------------------------------
-- A coach reads their own row, not the staff list
--
-- is_coach() is security definer and so is unaffected; it is the only thing
-- that needs to see other rows.
-- ---------------------------------------------------------------------------
drop policy if exists "coaches readable by authenticated" on coaches;

create policy "coach reads own row"
  on coaches for select to authenticated
  using (id = auth.uid());

-- ===== supabase/migrations/0008_status_values.sql =====

-- The coaches' five marks, corrected
--
-- The app shipped with four statuses and, critically, with X meaning "not
-- seen". It means the opposite. Confirmed with Brad and Tim on 2026-09-02,
-- which matches what their workbook already implied: its grid formula writes X
-- when the lesson log recorded that topic as done, and X outnumbers the tick
-- 3400 to 34 -- under the old reading, nobody at the centre had ever finished
-- anything.
--
-- The real key, in their order of progression:
--
--   (blank)  none
--   I        seen one time
--   R        seen multiple times      <- new, was missing entirely
--   T        test
--   X        complete                 <- was "not seen"
--
-- RENAME preserves every existing row, so no data migration is needed:
-- 'seen' rows become 'seen_once' and 'checked_off' rows become 'complete',
-- which is what they always meant.
--
-- This file contains nothing but the type change. Postgres permits ADD VALUE
-- inside a transaction but forbids *using* the new value in that same
-- transaction, and apply-sql.mjs wraps each file in one -- so anything that
-- writes 'seen_multiple' has to live in a later migration.

alter type progress_status rename value 'seen' to 'seen_once';
alter type progress_status rename value 'checked_off' to 'complete';
alter type progress_status add value 'seen_multiple' after 'seen_once';

-- ===== supabase/migrations/0009_roles.sql =====

-- Two kinds of coach
--
-- The centre has no automatic backups on the free tier, so a delete made by
-- accident during a class is not recoverable from anything but last night's
-- snapshot. Rather than making every coach cautious, the destructive acts are
-- moved behind a separate Admin login that nobody is signed into by default.
--
-- The line is drawn by blast radius, not by how "advanced" an action feels:
--
--   a class (session)      any coach   affects one day; cancelling classes is routine
--   a repeating class      any coach   same, and it spares sessions with attendance
--   a topic                Admin       cascades to every student's record of it
--   a level                Admin       cascades to every topic beneath it
--   a student              Admin       true deletion; "Remove" on the roster is
--                                      deactivation and stays open to coaches
--   progress rows          Admin       only ever removed by cascade in practice
--
-- Coaches keep delete on attendance -- un-checking someone in is routine -- and
-- on their own session notes.

create type coach_role as enum ('coach', 'admin');

alter table coaches add column role coach_role not null default 'coach';

-- Mirrors public.is_coach() in 0001. Security definer so it can read the
-- coaches table regardless of that table's own policies.
create or replace function public.is_admin()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from coaches where id = auth.uid() and role = 'admin'
  );
$$;

grant execute on function public.is_admin() to authenticated;

-- ---------------------------------------------------------------------------
-- Replace the blanket "coach full access" policies with per-command ones.
-- Reading, creating and editing stay at coach level everywhere; only DELETE
-- differs, table by table.
-- ---------------------------------------------------------------------------
do $$
declare
  v_table text;
  v_admin_only boolean;
begin
  foreach v_table in array array[
    'levels', 'topics', 'students', 'progress',
    'sessions', 'attendance', 'session_notes', 'class_series'
  ] loop
    v_admin_only := v_table in ('levels', 'topics', 'students', 'progress');

    execute format('drop policy if exists "coach full access" on public.%I', v_table);

    execute format(
      'create policy "coach reads" on public.%I for select to authenticated
         using (public.is_coach())', v_table);
    execute format(
      'create policy "coach creates" on public.%I for insert to authenticated
         with check (public.is_coach())', v_table);
    execute format(
      'create policy "coach edits" on public.%I for update to authenticated
         using (public.is_coach()) with check (public.is_coach())', v_table);

    if v_admin_only then
      execute format(
        'create policy "admin deletes" on public.%I for delete to authenticated
           using (public.is_admin())', v_table);
    else
      execute format(
        'create policy "coach deletes" on public.%I for delete to authenticated
           using (public.is_coach())', v_table);
    end if;
  end loop;
end
$$;

-- ===== supabase/migrations/0010_programs.sql =====

-- Chess is no longer the only thing the centre teaches
--
-- Coding classes are coming, and a child may well do both at once. That single
-- fact is why this is a table rather than a label: students.current_level_id
-- can only hold one level, so "Chess Level 2 and Coding Level 1" is
-- unrepresentable. Enrollments replace it.
--
-- Sessions gain a programme too. Without it, a grid cannot tell which of a
-- student's levels it is supposed to be showing.

create table programs (
  id         uuid primary key default gen_random_uuid(),
  name       text        not null unique,
  sort_order int         not null default 1,
  created_at timestamptz not null default now()
);

insert into programs (name, sort_order) values ('Chess', 1);

-- ---------------------------------------------------------------------------
-- Levels belong to a programme. Level 1 of chess and Level 1 of coding are
-- different things, so the number is only unique within a programme.
-- ---------------------------------------------------------------------------
alter table levels add column program_id uuid references programs (id) on delete cascade;
update levels set program_id = (select id from programs where name = 'Chess');
alter table levels alter column program_id set not null;

alter table levels drop constraint levels_number_key;
alter table levels add constraint levels_program_number_key unique (program_id, number);

-- ---------------------------------------------------------------------------
-- A class belongs to a programme
-- ---------------------------------------------------------------------------
alter table sessions add column program_id uuid references programs (id);
update sessions set program_id = (select id from programs where name = 'Chess');
alter table sessions alter column program_id set not null;

alter table class_series add column program_id uuid references programs (id);
update class_series set program_id = (select id from programs where name = 'Chess');
alter table class_series alter column program_id set not null;

create index sessions_program_idx on sessions (program_id);

-- ---------------------------------------------------------------------------
-- Enrollment: one row per student per programme, holding the level they are
-- currently at in it.
-- ---------------------------------------------------------------------------
create table enrollments (
  student_id uuid        not null references students (id) on delete cascade,
  program_id uuid        not null references programs (id) on delete cascade,
  level_id   uuid        references levels (id),
  created_at timestamptz not null default now(),
  primary key (student_id, program_id)
);

create index enrollments_level_idx on enrollments (level_id);

insert into enrollments (student_id, program_id, level_id)
select s.id, (select id from programs where name = 'Chess'), s.current_level_id
  from students s
 where s.current_level_id is not null;

-- ---------------------------------------------------------------------------
-- The "fill in a blank row for every topic" trigger moves from students to
-- enrollments, since that is now where a level is recorded.
-- ---------------------------------------------------------------------------
drop trigger if exists students_ensure_progress_ins on students;
drop trigger if exists students_ensure_progress_upd on students;

create or replace function public.ensure_progress_rows(p_student_id uuid)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  insert into progress (student_id, topic_id, status)
  select e.student_id, t.id, 'not_seen'::progress_status
    from enrollments e
    join topics t on t.level_id = e.level_id
   where e.student_id = p_student_id
  on conflict (student_id, topic_id) do nothing;
end;
$$;

create or replace function public.enrollments_ensure_progress()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if new.level_id is not null then
    perform public.ensure_progress_rows(new.student_id);
  end if;
  return new;
end;
$$;

create trigger enrollments_ensure_progress_ins
  after insert on enrollments
  for each row
  execute function public.enrollments_ensure_progress();

create trigger enrollments_ensure_progress_upd
  after update of level_id on enrollments
  for each row
  when (new.level_id is distinct from old.level_id)
  execute function public.enrollments_ensure_progress();

-- Adding a topic must reach students through their enrollment now.
create or replace function public.add_topic(p_level_id uuid, p_name text)
returns uuid
language plpgsql
set search_path = public
as $$
declare
  v_id uuid;
begin
  insert into topics (level_id, name, sort_order)
  select p_level_id,
         p_name,
         coalesce(max(sort_order), 0) + 1
    from topics
   where level_id = p_level_id
  returning id into v_id;

  insert into progress (student_id, topic_id, status)
  select e.student_id, v_id, 'not_seen'::progress_status
    from enrollments e
   where e.level_id = p_level_id
  on conflict (student_id, topic_id) do nothing;

  return v_id;
end;
$$;

alter table students drop column current_level_id;

-- ---------------------------------------------------------------------------
-- Security. New tables inherit nothing; see 0003 and 0009.
-- ---------------------------------------------------------------------------
alter table programs    enable row level security;
alter table enrollments enable row level security;

create policy "coach reads"   on programs for select to authenticated using (public.is_coach());
create policy "coach creates" on programs for insert to authenticated with check (public.is_coach());
create policy "coach edits"   on programs for update to authenticated using (public.is_coach()) with check (public.is_coach());
-- Deleting a programme cascades to its levels, and through them to every topic.
create policy "admin deletes" on programs for delete to authenticated using (public.is_admin());

create policy "coach reads"   on enrollments for select to authenticated using (public.is_coach());
create policy "coach creates" on enrollments for insert to authenticated with check (public.is_coach());
create policy "coach edits"   on enrollments for update to authenticated using (public.is_coach()) with check (public.is_coach());
-- Unenrolling destroys nothing: progress hangs off topics, so re-enrolling
-- restores exactly what was there.
create policy "coach deletes" on enrollments for delete to authenticated using (public.is_coach());

grant select, insert, update, delete on public.programs    to authenticated;
grant select, insert, update, delete on public.enrollments to authenticated;
grant select, insert, update, delete on public.programs    to service_role;
grant select, insert, update, delete on public.enrollments to service_role;
revoke all on public.programs    from anon;
revoke all on public.enrollments from anon;
revoke truncate on public.programs, public.enrollments from authenticated;

-- ===== supabase/migrations/0011_regulars_and_coverage.sql =====

-- Regulars, and what a class actually covered
--
-- Two small tables that carry most of what the coaches asked for after seeing
-- the demo.
--
-- REGULARS. Nearly everyone in a given class attends nearly every week -- in
-- their old tool every name carried a star. Ticking thirty of them one at a
-- time, every session, is the kind of friction that gets an app abandoned. The
-- star belongs to the *class*, not the student: "the Wednesday Level 1 regulars"
-- is the useful set, and drop-ins remain ordinary students who get checked in
-- by hand.
--
-- COVERAGE. Recording which topics a class covered gives the session log
-- something worth reading, and it is what the one-press advance below works
-- from -- so nothing is ever marked against a topic the class did not touch.

create table class_regulars (
  series_id  uuid        not null references class_series (id) on delete cascade,
  student_id uuid        not null references students (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (series_id, student_id)
);

create index class_regulars_student_idx on class_regulars (student_id);

create table session_topics (
  session_id uuid        not null references sessions (id) on delete cascade,
  topic_id   uuid        not null references topics (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (session_id, topic_id)
);

create index session_topics_topic_idx on session_topics (topic_id);

-- ---------------------------------------------------------------------------
-- One press: everyone present moves one step on the topics covered today.
--
-- The ceiling is deliberate and absolute. Attending a lesson is evidence a
-- student has *seen* something; it is not evidence they understood it, and it
-- is certainly not a test result. So this only ever does:
--
--     none -> seen once -> seen multiple times
--
-- and stops. Test and Complete are a coach's judgement about a particular
-- child and are only ever set by hand. Nothing is regressed either: a student
-- already at T or X is left exactly as they are.
--
-- Idempotent in the sense that matters: pressing it twice in one class moves
-- everyone twice, which is what "we covered it twice" would mean, but it can
-- never walk past R however many times it is pressed.
-- ---------------------------------------------------------------------------
create or replace function public.advance_session_topics(p_session_id uuid)
returns int
language plpgsql
set search_path = public
as $$
declare
  v_changed int;
begin
  update progress p
     set status = case p.status
                    when 'not_seen'  then 'seen_once'::progress_status
                    when 'seen_once' then 'seen_multiple'::progress_status
                  end,
         updated_at = now(),
         updated_by = auth.uid()
    from attendance a
    join sessions s   on s.id = a.session_id
    join enrollments e on e.student_id = a.student_id
                      and e.program_id = s.program_id
    join session_topics st on st.session_id = a.session_id
    join topics t on t.id = st.topic_id
                 and t.level_id = e.level_id
   where a.session_id = p_session_id
     and p.student_id = a.student_id
     and p.topic_id   = t.id
     and p.status in ('not_seen', 'seen_once');

  get diagnostics v_changed = row_count;
  return v_changed;
end;
$$;

-- ---------------------------------------------------------------------------
-- Security
-- ---------------------------------------------------------------------------
alter table class_regulars enable row level security;
alter table session_topics enable row level security;

create policy "coach reads"   on class_regulars for select to authenticated using (public.is_coach());
create policy "coach creates" on class_regulars for insert to authenticated with check (public.is_coach());
create policy "coach edits"   on class_regulars for update to authenticated using (public.is_coach()) with check (public.is_coach());
create policy "coach deletes" on class_regulars for delete to authenticated using (public.is_coach());

create policy "coach reads"   on session_topics for select to authenticated using (public.is_coach());
create policy "coach creates" on session_topics for insert to authenticated with check (public.is_coach());
create policy "coach edits"   on session_topics for update to authenticated using (public.is_coach()) with check (public.is_coach());
create policy "coach deletes" on session_topics for delete to authenticated using (public.is_coach());

grant select, insert, update, delete on public.class_regulars to authenticated;
grant select, insert, update, delete on public.session_topics to authenticated;
grant select, insert, update, delete on public.class_regulars to service_role;
grant select, insert, update, delete on public.session_topics to service_role;
grant execute on function public.advance_session_topics(uuid) to authenticated;
revoke all on public.class_regulars, public.session_topics from anon;
revoke truncate on public.class_regulars, public.session_topics from authenticated;

-- ===== supabase/migrations/0012_progress_history.sql =====

-- What changed, when, and in whose class
--
-- `progress` holds where a student stands now; it cannot answer "what did she
-- actually get out of last Wednesday". The coaches asked to see progress
-- against dates, which needs the changes kept, not just the latest value.
--
-- Recorded by a trigger rather than by the application, so every path is
-- covered: the grid, the one-press advance, an import, or a coach's own SQL.
-- Anything that writes a status writes its history.

create table progress_events (
  id          bigint generated always as identity primary key,
  student_id  uuid            not null references students (id) on delete cascade,
  topic_id    uuid            not null references topics (id)   on delete cascade,
  from_status progress_status,
  to_status   progress_status not null,
  -- Which class it happened in, when it happened in one at all.
  session_id  uuid            references sessions (id) on delete set null,
  changed_at  timestamptz     not null default now(),
  changed_by  uuid            references coaches (id)
);

create index progress_events_student_idx on progress_events (student_id, changed_at desc);
create index progress_events_session_idx on progress_events (session_id);

-- The session is passed through a transaction-local setting rather than as a
-- column on `progress`, because it is a property of the *change*, not of the
-- student's current state.
create or replace function public.record_progress_event()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  v_session uuid;
begin
  -- Nothing happened.
  if tg_op = 'UPDATE' and new.status is not distinct from old.status then
    return new;
  end if;

  -- The blank rows created when a student joins a level are not history; they
  -- are the absence of it. Logging 22 "became none" events per enrollment
  -- would bury the real entries.
  if tg_op = 'INSERT' and new.status = 'not_seen' then
    return new;
  end if;

  begin
    v_session := nullif(current_setting('app.session_id', true), '')::uuid;
  exception when others then
    v_session := null;
  end;

  insert into progress_events (
    student_id, topic_id, from_status, to_status, session_id, changed_by
  )
  values (
    new.student_id,
    new.topic_id,
    case when tg_op = 'UPDATE' then old.status else null end,
    new.status,
    v_session,
    -- auth.uid() is null for maintenance scripts, and may be a user with no
    -- coaches row; either way this must not break the write.
    (select id from coaches where id = auth.uid())
  );

  return new;
end;
$$;

create trigger progress_record_event
  after insert or update of status on progress
  for each row
  execute function public.record_progress_event();

-- ---------------------------------------------------------------------------
-- One entry point for marking a cell, so the class it happened in is recorded
-- with it. Security invoker: the coach's own policies still apply.
-- ---------------------------------------------------------------------------
create or replace function public.set_progress(
  p_student_id uuid,
  p_topic_id   uuid,
  p_status     progress_status,
  p_session_id uuid default null
)
returns void
language plpgsql
set search_path = public
as $$
begin
  perform set_config('app.session_id', coalesce(p_session_id::text, ''), true);

  insert into progress (student_id, topic_id, status, updated_by)
  values (
    p_student_id,
    p_topic_id,
    p_status,
    (select id from coaches where id = auth.uid())
  )
  on conflict (student_id, topic_id) do update
     set status     = excluded.status,
         updated_at = now(),
         updated_by = excluded.updated_by;
end;
$$;

-- The bulk advance gets the same treatment, so a class's worth of marks is
-- attributed to that class.
create or replace function public.advance_session_topics(p_session_id uuid)
returns int
language plpgsql
set search_path = public
as $$
declare
  v_changed int;
begin
  perform set_config('app.session_id', p_session_id::text, true);

  update progress p
     set status = case p.status
                    when 'not_seen'  then 'seen_once'::progress_status
                    when 'seen_once' then 'seen_multiple'::progress_status
                  end,
         updated_at = now(),
         updated_by = (select id from coaches where id = auth.uid())
    from attendance a
    join sessions s   on s.id = a.session_id
    join enrollments e on e.student_id = a.student_id
                      and e.program_id = s.program_id
    join session_topics st on st.session_id = a.session_id
    join topics t on t.id = st.topic_id
                 and t.level_id = e.level_id
   where a.session_id = p_session_id
     and p.student_id = a.student_id
     and p.topic_id   = t.id
     and p.status in ('not_seen', 'seen_once');

  get diagnostics v_changed = row_count;
  return v_changed;
end;
$$;

alter table progress_events enable row level security;

create policy "coach reads" on progress_events
  for select to authenticated using (public.is_coach());
-- History is written by the trigger, never by hand, and is never edited.
create policy "admin deletes" on progress_events
  for delete to authenticated using (public.is_admin());

grant select on public.progress_events to authenticated;
grant select, insert, update, delete on public.progress_events to service_role;
grant execute on function public.set_progress(uuid, uuid, progress_status, uuid) to authenticated;
revoke all on public.progress_events from anon;

-- ===== supabase/migrations/0013_series_programs.sql =====

-- Generated classes must carry their programme
--
-- 0010 made sessions.program_id NOT NULL, but generate_series_sessions still
-- inserted without it, so "Extend 8 weeks" would have failed at runtime with a
-- constraint error. The tests caught it before anyone pressed the button.
--
-- A generated class simply inherits the programme of the series that produced
-- it, which is the only sensible answer.

create or replace function public.generate_series_sessions(
  p_series_id uuid,
  p_through   date
)
returns int
language plpgsql
set search_path = public
as $$
declare
  v_created int;
begin
  insert into sessions (session_date, session_time, series_id, created_by, program_id)
  select day::date, s.session_time, s.id, s.created_by, s.program_id
    from class_series s
    cross join generate_series(s.start_date, p_through, interval '1 day') as day
   where s.id = p_series_id
     and s.is_active
     and extract(dow from day)::int = any (s.weekdays)
  on conflict do nothing;

  get diagnostics v_created = row_count;
  return v_created;
end;
$$;

-- ===== supabase/migrations/0014_session_notes_column.sql =====

-- A note about the class itself
--
-- session_notes holds a note per student per class. The coaches' existing
-- system also has one about the class as a whole -- "no lesson, tournament
-- prep", that sort of thing -- and they use it. Without somewhere to put it,
-- those notes would be dropped on import.

alter table sessions add column notes text;

-- ===== supabase/migrations/0015_generate_all_series.sql =====

-- Classes that never run out
--
-- The centre's classes run indefinitely -- "they are always just on", as Nikhil
-- put it. But sessions are materialised up to a horizon, and topping that
-- horizon up was a button somebody had to remember to press. Nobody would, and
-- the calendar would quietly run dry: the demo had zero upcoming classes for
-- exactly this reason.
--
-- Materialising is still right. A coach has to be able to cancel one week
-- without a rule regenerating it, which a computed schedule cannot offer. What
-- changes is who does the topping up: a nightly job, not a person.
--
-- Safe to run as often as you like. generate_series_sessions only fills in
-- dates that are missing, so a second call in the same minute creates nothing
-- and a cancelled week stays cancelled.

create or replace function public.generate_all_series(p_through date)
returns int
language plpgsql
set search_path = public
as $$
declare
  v_series  record;
  v_created int := 0;
begin
  for v_series in select id from class_series where is_active loop
    v_created := v_created + public.generate_series_sessions(v_series.id, p_through);
  end loop;

  return v_created;
end;
$$;

grant execute on function public.generate_all_series(date) to authenticated;

-- ===== supabase/migrations/0016_merge_students.sql =====

-- Joining scattered pages into one child
--
-- Their system holds one page per student per level: 654 rows for roughly 490
-- children. Tim: "I will need to go through manually and assign each topic
-- sheet (Rohan level 2, Rohan M level 3, etc) to their appropriate profile."
--
-- This is that operation. It cannot be automated -- most pages carry a bare
-- first name, and merging the wrong two would fuse two children's records --
-- so a coach decides and this does the work.
--
-- WHO MAY DO IT. Coaches, not only Admin. It deletes a student row, which
-- would normally put it behind the Admin account, but nothing is lost when it
-- does: every mark, class, note and attendance moves to the surviving record
-- first. It is a data-cleanup chore the coaches have to work through over
-- weeks, and putting the Admin password in their hands for it would undo the
-- reason that account exists.

create table merge_dismissals (
  -- Ordered so a pair cannot be dismissed twice under two names.
  student_a    uuid        not null references students (id) on delete cascade,
  student_b    uuid        not null references students (id) on delete cascade,
  dismissed_at timestamptz not null default now(),
  dismissed_by uuid        references coaches (id),
  primary key (student_a, student_b),
  check (student_a < student_b)
);

alter table merge_dismissals enable row level security;

create policy "coach reads"   on merge_dismissals for select to authenticated using (public.is_coach());
create policy "coach creates" on merge_dismissals for insert to authenticated with check (public.is_coach());
create policy "coach deletes" on merge_dismissals for delete to authenticated using (public.is_coach());

grant select, insert, delete on public.merge_dismissals to authenticated;
grant select, insert, update, delete on public.merge_dismissals to service_role;
revoke all on public.merge_dismissals from anon;

-- ---------------------------------------------------------------------------
-- Merge p_absorb into p_keep.
--
-- Everything moves before anything is deleted, so a failure at any point rolls
-- back to two intact records rather than one damaged one.
-- ---------------------------------------------------------------------------
create or replace function public.merge_students(
  p_keep      uuid,
  p_absorb    uuid,
  p_full_name text default null
)
returns void
language plpgsql
security definer
set search_path = public
as $fn$
begin
  if not public.is_coach() then
    raise exception 'Only a coach can merge student records';
  end if;

  if p_keep = p_absorb then
    raise exception 'Cannot merge a student into themselves';
  end if;

  if not exists (select 1 from students where id = p_keep)
     or not exists (select 1 from students where id = p_absorb) then
    raise exception 'Both students must exist';
  end if;

  -- Attendance: the same child cannot be in one class twice, so collisions are
  -- simply dropped.
  insert into attendance (session_id, student_id, created_at)
  select session_id, p_keep, created_at from attendance where student_id = p_absorb
  on conflict (session_id, student_id) do nothing;
  delete from attendance where student_id = p_absorb;

  -- Notes: both are somebody's writing about a real lesson, so a collision
  -- keeps both rather than picking a winner.
  insert into session_notes (session_id, student_id, note_text, updated_at)
  select session_id, p_keep, note_text, updated_at
    from session_notes where student_id = p_absorb
  on conflict (session_id, student_id) do update
    set note_text = session_notes.note_text || E'\n' || excluded.note_text;
  delete from session_notes where student_id = p_absorb;

  insert into class_regulars (series_id, student_id, created_at)
  select series_id, p_keep, created_at from class_regulars where student_id = p_absorb
  on conflict (series_id, student_id) do nothing;
  delete from class_regulars where student_id = p_absorb;

  -- History carries over wholesale: it is a log, and there is nothing to
  -- collide on.
  update progress_events set student_id = p_keep where student_id = p_absorb;

  -- Progress. Rows for different levels never collide, which is the common
  -- case. Where the same topic exists on both pages, keep the mark that is
  -- further along -- a child who reached Complete on one page did reach it,
  -- and the enum is ordered so the comparison means what it reads as.
  insert into progress (student_id, topic_id, status, updated_at, updated_by)
  select p_keep, topic_id, status, updated_at, updated_by
    from progress where student_id = p_absorb
  on conflict (student_id, topic_id) do update
    set status = case
                   when excluded.status > progress.status then excluded.status
                   else progress.status
                 end;
  delete from progress where student_id = p_absorb;

  -- Enrollment: one per programme. Where both pages are in the same
  -- programme, the higher level wins, since that is where the child got to.
  -- Comma-style FROM rather than JOIN ... ON: an UPDATE cannot join back to
  -- its own target table inside the FROM clause, so the comparison against the
  -- kept row's level has to live in WHERE.
  update enrollments e
     set level_id = a.level_id
    from enrollments a, levels la, levels lk
   where a.student_id = p_absorb
     and e.student_id = p_keep
     and e.program_id = a.program_id
     and la.id = a.level_id
     and lk.id = e.level_id
     and la.number > lk.number;

  insert into enrollments (student_id, program_id, level_id, created_at)
  select p_keep, program_id, level_id, created_at
    from enrollments where student_id = p_absorb
  on conflict (student_id, program_id) do nothing;
  delete from enrollments where student_id = p_absorb;

  -- The proper name, if the coach supplied one: "these two pages are the same
  -- child, and she is Rohan Mistry".
  if p_full_name is not null and length(trim(p_full_name)) > 0 then
    update students set full_name = trim(p_full_name) where id = p_keep;
  end if;

  -- A page that was active anywhere makes the survivor active.
  update students k
     set is_active = true
    from students a
   where k.id = p_keep and a.id = p_absorb and a.is_active;

  delete from merge_dismissals
   where student_a = p_absorb or student_b = p_absorb;

  delete from students where id = p_absorb;
end;
$fn$;

grant execute on function public.merge_students(uuid, uuid, text) to authenticated;

-- ===== supabase/seed/000_coaches.sql =====

-- Coach rows, linking the three Supabase auth accounts to the coaches table.
--
-- NOT placeholder student data — the teardown script does NOT remove these.
-- On Wednesday, rename display_name and change the account emails/passwords in
-- the dashboard. The UUIDs stay the same, so nothing else needs to change.
--
-- Accounts were created pre-confirmed via the admin API on 2026-09-01:
--   brad@example.com / tim@example.com / spare@example.com

insert into coaches (id, display_name) values
  ('a9a43349-2e5e-4bde-933c-e282c37422a8', 'Brad'),
  ('1bab3d65-213c-4501-b844-44b201e74b85', 'Tim'),
  ('cb68d93d-7373-4f85-9730-1f6269ff5806', 'Spare')
on conflict (id) do nothing;
